CREATE TABLE temp_raw_products (
        id INTEGER PRIMARY KEY,
        name TEXT,
        brand_name TEXT,
        price REAL
    );

    INSERT INTO temp_raw_products
    SELECT id, name, brand, price
    FROM products
    LIMIT 30;

    CREATE TABLE temp_brands (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE
    );

    INSERT INTO temp_brands (name)
    SELECT DISTINCT brand_name
    FROM temp_raw_products
    ORDER BY brand_name;

    SELECT * FROM temp_brands ORDER BY id LIMIT 10;

    CREATE TABLE temp_norm_products (
        id INTEGER,
        name TEXT,
        brand_id INTEGER,
        price REAL
    );

    INSERT INTO temp_norm_products
    SELECT r.id, r.name, b.id, r.price
    FROM temp_raw_products AS r
    INNER JOIN temp_brands AS b ON r.brand_name = b.name;

    SELECT np.id, np.name, b.name AS brand, np.price
    FROM temp_norm_products AS np
    INNER JOIN temp_brands AS b ON np.brand_id = b.id
    ORDER BY b.name, np.name
    LIMIT 10;

    DROP TABLE temp_raw_products;
    DROP TABLE temp_brands;
    DROP TABLE temp_norm_products;
```

Explain the logic of this SQL query:
```sql
CREATE PROCEDURE sp_search_products(
        IN p_keyword VARCHAR(200),
        IN p_category_id INT,
        IN p_min_price DECIMAL(12,2),
        IN p_max_price DECIMAL(12,2),
        IN p_in_stock_only BOOLEAN
    )
    BEGIN
        SET @sql = 'SELECT p.id, p.name, p.brand, p.price, p.stock_qty, c.name AS category
                    FROM products p
                    JOIN categories c ON p.category_id = c.id
                    WHERE p.is_active = TRUE';
        SET @params = '';

        IF p_keyword IS NOT NULL AND p_keyword != '' THEN
            SET @sql = CONCAT(@sql, ' AND (p.name LIKE ? OR p.brand LIKE ? OR p.description LIKE ?)');
            SET @kw = CONCAT('%', p_keyword, '%');
        END IF;

        IF p_category_id IS NOT NULL THEN
            SET @sql = CONCAT(@sql, ' AND p.category_id = ', p_category_id);
        END IF;

        IF p_min_price IS NOT NULL THEN
            SET @sql = CONCAT(@sql, ' AND p.price >= ', p_min_price);
        END IF;

        IF p_max_price IS NOT NULL THEN
            SET @sql = CONCAT(@sql, ' AND p.price <= ', p_max_price);
        END IF;

        IF p_in_stock_only = TRUE THEN
            SET @sql = CONCAT(@sql, ' AND p.stock_qty > 0');
        END IF;

        SET @sql = CONCAT(@sql, ' ORDER BY p.name LIMIT 100');

        IF p_keyword IS NOT NULL AND p_keyword != '' THEN
            PREPARE stmt FROM @sql;
            EXECUTE stmt USING @kw, @kw, @kw;
            DEALLOCATE PREPARE stmt;
        ELSE
            PREPARE stmt FROM @sql;
            EXECUTE stmt;
            DEALLOCATE PREPARE stmt;
        END IF;
    END
```

